<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Star,Play,Flag,Copy} from 'lucide-vue-next'
import {api,newKey} from '../api'
import {useApp} from '../stores/app'
import {useRequestScope} from '../platform/request-scope'
import PageHeader from '../workspace/PageHeader.vue'
import PublicCover from './PublicCover.vue'
import Sheet from '../components/Sheet.vue'
import CharacterAvatar from '../components/CharacterAvatar.vue'
import type {PublicDetail} from './types'
import './authoring.css'
import {useCuratedArtwork} from '../catalog/curated-artwork'
const {publications}=useCuratedArtwork()
const route=useRoute(),router=useRouter(),store=useApp(),capture=useRequestScope(),id=String(route.params.publicationId),detail=ref<PublicDetail>(),selected=ref(''),busy=ref(false),error=ref(''),notice=ref(''),reporting=ref(false),reason=ref(''),copyKey=newKey();let receipt:{worldId:string}|undefined
async function load(){const scope=capture();error.value='';try{const result=await api<PublicDetail>('/authoring/publications/'+id);if(scope.valid()){detail.value=result;selected.value=result.openings[0]?.id||''}}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function favorite(){if(!detail.value||busy.value)return;const scope=capture(),next=!detail.value.favorite;busy.value=true;error.value='';try{await api('/authoring/publications/'+id+'/favorite',{method:'PUT',body:{favorite:next}});if(scope.valid()&&detail.value){detail.value.favorite=next;detail.value.favorites+=next?1:-1}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function play(){if(busy.value||!selected.value)return;const scope=capture();busy.value=true;error.value='';try{const result=receipt||await api<{worldId:string}>('/authoring/publications/'+id+'/copy',{method:'POST',body:{},key:copyKey});if(!scope.valid())return;receipt=result;await router.push({path:'/worlds/new',query:{world:result.worldId,opening:selected.value}})}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function report(){const scope=capture();busy.value=true;error.value='';try{await api('/authoring/publications/'+id+'/report',{method:'POST',body:{reason:reason.value}});if(scope.valid()){reporting.value=false;notice.value='举报已提交，管理员会在审核中心处理。';reason.value=''}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function share(){try{await navigator.clipboard.writeText(location.href);notice.value='作品链接已复制，打开后使用账号登录即可查看。'}catch{notice.value='可以复制浏览器地址栏分享此作品。'}}
onMounted(load)
</script>
<template><div class="workspace-page"><PageHeader :title="detail?.title||'公开作品'" eyebrow="公开作品" :description="detail?.summary||'通过审核的互动故事。'"></PageHeader><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status" class="product-hint">{{notice}}</p><template v-if="detail"><section class="workspace-card author-columns"><PublicCover :id="id" :title="detail.title" :theme="detail.coverTheme" :has-cover="detail.hasCover" :cover-key="publications.get(id)"/><div><RouterLink :to="'/authors/'+detail.authorId" class="inline-link">作者：{{detail.authorName}}</RouterLink><p>公开版本 {{detail.version}} · {{detail.favorites}} 人收藏</p><p class="author-prose">{{detail.introduction}}</p><p v-if="detail.tags.length">{{detail.tags.join(' · ')}}</p><p class="muted">来源与授权：{{detail.attribution}}</p><div class="public-actions"><button :disabled="busy||!store.online" :aria-pressed="detail.favorite" @click="favorite"><Star :size="17"/>{{detail.favorite?'取消收藏':'收藏作品'}}</button><button @click="share"><Copy :size="17"/>分享链接</button><button :disabled="!store.online" @click="reporting=true"><Flag :size="17"/>举报作品</button></div></div></section><section class="workspace-card" style="margin-top:24px"><h2>故事中的人物</h2><div class="public-character-faces"><div v-for="person in detail.characters" :key="person.id"><CharacterAvatar :entity-id="person.id" :name="person.name" :image-url="person.avatarUrl" :size="48"/><span>{{person.name}}</span></div></div><h2>选择你的开局</h2><button v-for="opening in detail.openings" :key="opening.id" class="public-opening" :aria-pressed="selected===opening.id" @click="selected=opening.id"><strong>{{opening.title}}</strong><small>{{opening.description}}</small><span>{{opening.text}}</span></button><p>开始后，在自己的账号中确认身份和开局信息。你的世界线独立保存，作者更新或撤下作品不会覆盖它。</p><button class="primary" :disabled="busy||!store.online||!selected" @click="play"><Play :size="17"/>{{busy?'正在打开…':'使用这个开局'}}</button></section></template><Sheet v-if="reporting" title="举报公开作品" @close="!busy&&(reporting=false)"><p>请说明具体问题，例如内容、授权或隐私问题。你的举报不会公开展示。</p><label>举报原因<textarea v-model="reason" minlength="5" maxlength="1000" rows="5"></textarea></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="busy||reason.trim().length<5" @click="report">提交举报</button></Sheet></div></template>

<style scoped>.public-character-faces{display:flex;gap:18px;flex-wrap:wrap;margin:20px 0 28px}.public-character-faces>div{display:grid;justify-items:center;gap:8px;font-size:13px}</style>
